# ============================================================

cat("\n============================================================\n")
cat("CANDIDATE MP FIGURES AND TABLES COMPLETED\n")
cat("============================================================\n")
cat("Scenario:",scenario_label,"\n")
cat("Scenario tag:",scenario_tag,"\n")
cat("Candidate MPs:",nrow(scenario_grid),"\n")
cat("Fcap values:",paste(sort(unique(scenario_grid$Fcap)),collapse=", "),"\n")
cat("Besc values:",paste(sort(unique(scenario_grid$Besc)),collapse=", "),"\n")
cat("Horizons:",paste(horizon_order,collapse=", "),"\n")
cat("Figures:",fig_dir,"\n")
cat("Tables:",table_dir,"\n")